window.MW_TXN={"grip-strength":"Grip Strength","truage":"TruAge + TruHealth","glycanage":"GlycanAge","neuromodulators": "Neuromodulators", "therapeutic-botox": "Therapeutic Neuromodulators", "dermal-fillers": "Dermal Fillers", "sculptra": "Sculptra", "biofiller": "Biofiller", "skin-boosters": "Skin Boosters", "microneedling": "Microneedling", "exosome-facial": "Exosomes", "meta-cell-technology": "Meta Cell Technology", "medical-grade-skincare": "Medical-Grade Skincare", "prp-hair-restoration": "PRP / PRF for Hair", "exosome-hair-therapy": "Exosome Hair Therapy", "alopecia-injections": "Corticosteroid Injections for Alopecia", "ultrasound-guided-prp": "Ultrasound-Guided PRP", "knee-oa-injections": "Hyaluronic Acid Knee Injections", "prolotherapy": "Prolotherapy", "prp-for-pain": "PRP for Pain", "trigger-point-injections": "Trigger Point Injections", "glp1-support": "GLP-1 Support", "slimworks": "Slimworks Protocol", "insulin-resistance": "Insulin Resistance Treatment", "guided-fasting": "Fasting Protocols", "prolon": "Prolon FMD", "styku-scan": "Styku 3D Body Scan", "rmr": "Resting Metabolic Rate (RMR)", "lab-vw-oat": "Organic Acids Test (OAT)", "pillcheck": "Pillcheck Drug Response Test", "iron-ferritin": "Iron & Ferritin Testing", "autoimmune-panel": "Autoimmune & Inflammation Panel", "dexa-scan": "DEXA Scan", "bhrt": "Bioidentical Hormones (BHRT)", "trt": "Testosterone Replacement Therapy (TRT)", "vo2-max": "VO2 Max Testing", "genomics": "totalPower DNA Test", "mitochondria-rehab": "Mitochondria Rehab", "liveo2": "LiveO2 Adaptive Contrast", "red-light-therapy": "ARRC Red Light", "vasper": "Vasper", "aesthetic-consultation": "Naturopathic Aesthetic Consultation", "hair-consultation": "Naturopathic Hair Consultation", "naturopathic-consultation": "Naturopathic Consultation", "functional-lab-testing": "Functional Lab Testing", "lifelabs-testing": "Conventional Labs (LifeLabs)", "holistic-nutrition": "Holistic Nutrition", "supplement-protocols": "Supplements", "slit": "Sublingual Immunotherapy", "myers-cocktail": "IV Nutrient Therapy", "nad-iv": "NAD+ IV", "pc-iv": "Phosphatidylcholine IV", "glutathione-iv": "Glutathione IV", "prp-facial": "PRP Facial", "prf-facial": "PRF", "prfm": "PRFM", "pharmaceuticals-hair": "Pharmaceutical Hair Treatment", "growth-hormone": "Growth Hormone Therapy", "hormone-testing": "Comprehensive Hormone Testing", "lipotropic-injections": "Lipotropic Injections", "homa-ir": "Insulin Resistance (HOMA-IR)", "arterial-stiffness": "Arterial Stiffness Index", "dna-supplements": "DNA-Personalized Supplements", "selfdecode": "SelfDecode Whole Genome"};
